'use strict'

module.exports = (...args) => {
  const { data, hash: params } = args.pop()
  const ref = args[0]
  if (!ref) return
  const { contentCatalog, page } = data.root
  let publishable
  if ('publishable' in params) {
    publishable = params.publishable
    delete params.publishable
  }
  const context = page.component
    ? Object.assign({ component: page.component.name, version: page.version, module: page.module }, params)
    : params
  const file = contentCatalog.resolveResource(ref, context)
  if (file && publishable != null && !(file.out ? publishable : !publishable)) return
  return file
}
